SELECT
 T.SALES_TERRITORY_KEY,
 T.SALES_REP_NUMBER AS SALES_REP_NUM,
 T.DV_ATTRIBUTION_CD,
 T.DV_SALES_ORDER_LINE_KEY,
 T.ANNUAL_NET AS DV_ANNUAL_NET_AMT,
 T.SALES_ORDER_KEY,
 T.CNTRCT_DURATION AS DV_CONTRACT_DURATION,
 T.BKGS_MEASURE_TRANS_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CD,
 T.CORPORATE_BOOKINGS_FLG,
 T.REVENUE_RECOGNITION_FLG AS DV_REVENUE_RECOGNITION_FLG,
 T.CONTRACT_START_DATE AS RU_SERVICE_CONTRACT_START_DTM,
 T.CONTRACT_END_DATE AS RU_SERVICE_CONTRACT_END_DTM,
 T.ANNUALIZD_FLAG AS DV_ANNUALIZED_FLG,
 T.SHIP_TO_CUSTOMER_KEY,
 T.SERVICE_FLG,
 T.DV_PRODUCT_KEY,
 T.BILL_TO_CUSTOMER_KEY,
 T.BOOKINGS_MEASURE_KEY,
 T.END_CUSTOMER_KEY_NOT_OFFSETED AS NOT_OFFSETED_END_CUSTOMER_KEY,
 T.END_CUSTOMER_KEY AS DV_END_CUSTOMER_KEY,
 T.BOOKINGS_PROCESS_DATE AS BOOKINGS_PROCESS_DT,
 T.POS_TRX_ID_INT AS BK_POS_TRANSACTION_ID_INT,
 T.SOURCE_ORDER_NUMBER AS DV_SOURCE_ORDER_NUM_INT,
 T.NET_SPREAD_FLG AS DV_NET_SPREAD_FLG,
 T.DV_AR_TRX_LINE_KEY,
 T.TRANSACTION_DATETIME AS TRANSACTION_DTM,
 T.CANCEL_CODE AS CANCEL_CD,
 T.IC_REVENUE_FLG,
 T.CHARGES_FLG,
 T.MISC_FLG,
 T.INTERNATIONAL_DEMO_FLG,
 T.REPLACEMENT_DEMO_FLG,
 T.REVENUE_FLG,
 T.CONVERSION_RT,
 T.TRANSACTION_NAME AS DV_TRANSACTION_NAME,
 T.FMV_FLG AS DV_FMV_FLG,
 T.XCAT_FLAG AS XCAT_FLG,
 T.OFFER_TYPE_NAME AS BK_OFFER_TYPE_NAME,
 T.RECURRING_OFFER_FLAG AS RECURRING_OFFER_FLG,
 T.ELA_FLG,
 T.FISCAL_YEAR_MTH_INT AS DV_FISCAL_YEAR_MTH_NUMBER_INT,
 T.SALES_ADJ_LINE_NUMBER_INT AS BK_SALES_ADJ_LINE_NUMBER_INT,
 T.SALES_ADJ_NUMBER_INT AS BK_SALES_ADJ_NUMBER_INT,
 T.DEAL_ID AS DV_DEAL_ID,
 T.REVENUE_TRANSFER_KEY,
 T.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY,
 T.SK_OFFER_ATTRIBUTION_ID_INT,
 T.ADJUSTMENT_TYPE_CODE AS ADJUSTMENT_TYPE_CD,
 ---- SHOULD CHK
 T.ADJUSTMENT_CODE AS IDE_ADJUSTMENT_CD,
 T.SOLD_TO_CUSTOMER_KEY,
 T.PARTNER_SITE_PARTY_KEY,
 T.ROUTE_TO_MARKET_CD AS DV_ROUTE_TO_MARKET_CD,
 T.AS_OF_FSC_MTH_RTM_CD AS DV_AS_OF_FSC_MTH_RTM_CD,
 T.BOOKINGS_NET AS DV_CA_SERVICE_BOOOKINGS_PCT,
 COALESCE(T.MY_NET,0) AS DV_MY_NET_PCT,
 T.PRODUCT_CLASSIFICATION AS BK_PRDT_ALLCTN_CLSFCTN_CD,
 T.WEEK_NAME AS FISCAL_WEEK_NAME,
 T.PERIOD_ID AS FISCAL_YEAR_MONTH_INT,
 T.WEEK_ID AS DV_FISCAL_YR_MNTH_WEEK_NUM_INT,
 'UNKNOWN' as RU_BK_SERVICE_PROD_SUBGROUP_ID,
 T.PRODUCT_KEY,
 T.ANNUITY_AMT,
 'N' AS TRUE_UP_FLG,
 'AMY' AS BOOKING_TYPE_CD,
 T.ANNUITY_SWITCHING AS ANNUITY_SWITCHING_NUM,
 CURRENT_TIMESTAMP(0) AS EDW_CREATE_DTM,
 CURRENT_USER AS EDW_CREATE_USER,
 CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DTM,
 CURRENT_USER AS EDW_UPDATE_USER,
 T.SALES_MOTION_CD,
 T.SUMMARY_QUOTE_FLG,
 T.ADJUSTMENT_DESCR_KEY,
 T.DV_RECURRING_OFFER_CD,
 T.SK_SALES_MOTION_ATTRIB_KEY,
 T.WIPS_ORIGINATOR_ID_INT,
 /*Added as part of SFP Q4FY21 Rel*/
 T.MAGIC_KEY_ID,
 T.DSV_FLG
 FROM
 (
  SELECT
   RSTD.DV_SALES_ORDER_LINE_KEY,
   RSTD.DV_ATTRIBUTION_CD,
   RSTD.PRODUCT_KEY,
   RSTD.SALES_TERRITORY_KEY,
   RSTD.SALES_REP_NUMBER,
   RSTD.SALES_ORDER_KEY,
   RSTD.BKGS_MEASURE_TRANS_TYPE_CODE,
   RSTD.CORPORATE_BOOKINGS_FLG,
   RSTD.SERVICE_FLG,
   RSTD.DV_PRODUCT_KEY,
   RSTD.BILL_TO_CUSTOMER_KEY,
   RSTD.SHIP_TO_CUSTOMER_KEY,
   --RFDY.DV_FISCAL_QUARTER_ID AS QUARTER_ID,
   RSTD.BOOKINGS_MEASURE_KEY,
   RSTD.BOOKINGS_PROCESS_DATE,
   RSTD.ADJUSTMENT_TYPE_CODE,
   RSTD.ADJUSTMENT_CODE,
   RSTD.DV_AR_TRX_LINE_KEY,
   RSTD.SOLD_TO_CUSTOMER_KEY,
   RSTD.DV_END_CUSTOMER_KEY END_CUSTOMER_KEY,
   RSTD.SK_OFFER_ATTRIBUTION_ID_INT,
   NBCM.PARTNER_SITE_PARTY_KEY,
   RSTD.ELA_FLG,
   --RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT AS QUARTER_NUMBER_INT,
   RSTD.DSV_FLG,
   RSTD.REVENUE_FLG,
   RSTD.IC_REVENUE_FLG,
   RSTD.REPLACEMENT_DEMO_FLG,
   RSTD.INTERNATIONAL_DEMO_FLG,
   RSTD.CHARGES_FLG,
   RSTD.MISC_FLG,
   RSTD.TRANSACTION_DATETIME,
   RSTD.CANCEL_CODE,
   RSTD.CONVERSION_RT,
   RSTD.REVENUE_TRANSFER_KEY,
   RSTD.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY,
   RSTD.SALES_MOTION_CD,
   RSTD.SUMMARY_QUOTE_FLG,
   RSTD.ADJUSTMENT_DESCR_KEY,
   RSTD.DV_RECURRING_OFFER_CD,
   RSTD.SK_SALES_MOTION_ATTRIB_KEY,
   RSTD.WIPS_ORIGINATOR_ID_INT,
   /*Added as part of SFP Q4FY21 Rel*/
   NBCM.MAGIC_KEY_ID,
   (RSTD.DD_COMP_US_NET_PRICE_AMOUNT * NPCA.ALLOCATION_PCT) AS BOOKINGS_NET,
   CASE
    WHEN COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') = 'Hardware'
     THEN RSTD.DD_COMP_US_NET_PRICE_AMOUNT * NPCA.ALLOCATION_PCT
   ELSE RSTD.DV_ANNUALIZED_US_NET_AMT * NPCA.ALLOCATION_PCT
   END ANNUAL_NET,
   NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD PRODUCT_CLASSIFICATION,
   CASE
    WHEN COLLATE(PRODUCT_CLASSIFICATION, 'en-ci-rtrim') = 'Software'
     THEN CASE
      WHEN COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') = 'Hardware'
       THEN 0
    ELSE RSTD.DV_MULTIYEAR_US_NET_AMT * NPCA.ALLOCATION_PCT
     END
   ELSE CAST(0.00 AS DECIMAL(36, 8))
   END AS MY_NET,
   CAST(0.00 AS DECIMAL(18, 6)) AS ANNUITY_AMT,
   RFDY.FISCAL_YEAR_MONTH_INT AS PERIOD_ID,
   RSTD.DV_CONTRACT_DURATION AS CNTRCT_DURATION,
   RSTD.RU_SERVICE_CONTRACT_START_DTM AS CONTRACT_START_DATE,
   RSTD.RU_SERVICE_CONTRACT_END_DTM AS CONTRACT_END_DATE,
   CASE
    WHEN COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') = 'Hardware'
     THEN 'Y'
   ELSE RSTD.DV_ANNUALIZED_FLG
   END ANNUALIZD_FLAG,
   RSTD.DV_REVENUE_RECOGNITION_FLG REVENUE_RECOGNITION_FLG,
   RFDY.FISCAL_WEEK_NAME AS WEEK_NAME,
   RFDY.DV_FISCAL_YR_MNTH_WEEK_NUM_INT AS WEEK_ID,
   RSTD.DV_NET_SPREAD_FLG NET_SPREAD_FLG,
   RSTD.DV_SOURCE_ORDER_NUM_INT AS SOURCE_ORDER_NUMBER,
   RSTD.BK_POS_TRANSACTION_ID_INT AS POS_TRX_ID_INT,
   RSTD.END_CUSTOMER_KEY END_CUSTOMER_KEY_NOT_OFFSETED,
   RSTD.DV_FMV_FLG FMV_FLG,
   --Dummy Column to keep the default view intact.
   CAST(1 AS NUMBER(38, 18)) AS ANNUITY_SWITCHING,
   RSTD.BK_OFFER_TYPE_NAME OFFER_TYPE_NAME,
   RSTD.XCAT_FLG XCAT_FLAG,
   RSTD.RECURRING_OFFER_FLG RECURRING_OFFER_FLAG,
   NBCM.DV_ROUTE_TO_MARKET_CD ROUTE_TO_MARKET_CD,
   NBCM.DV_AS_OF_FSC_MTH_RTM_CD AS_OF_FSC_MTH_RTM_CD,
   RSTD.DV_TRANSACTION_NAME TRANSACTION_NAME,
   RSTD.BK_SALES_ADJ_LINE_NUMBER_INT SALES_ADJ_LINE_NUMBER_INT,
   RSTD.BK_SALES_ADJ_NUMBER_INT SALES_ADJ_NUMBER_INT,
   RSTD.DV_DEAL_ID DEAL_ID,
   RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT AS FISCAL_YEAR_MTH_INT

   FROM /*BV_RSTD_BKGS_MSR_ANLZD_MY*/
   {{ source('raw', 'MT_RSTD_BKGS_MEASURE') }} RSTD
   INNER JOIN
    {{ source('raw', 'N_BOOKINGS_CHANNEL_MEASURE') }} NBCM
   ON RSTD.BOOKINGS_MEASURE_KEY = NBCM.BOOKINGS_MEASURE_KEY
   AND  RSTD.BOOKINGS_PROCESS_DATE = NBCM.BOOKINGS_PROCESS_DATE
   AND RSTD.BKGS_MEASURE_TRANS_TYPE_CODE = NBCM.BKGS_MEASURE_TRANS_TYPE_CODE
   INNER JOIN
    {{ source('raw', 'N_PRDT_TO_PRDT_CLSFTN_ALCTN') }} NPCA
   ON  NPCA.DV_FISCAL_YEAR_QUARTER_NUM_INT = RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT
   AND NPCA.PRODUCT_KEY = RSTD.PRODUCT_KEY
   AND RTRIM( NPCA.BK_PRDT_ALLCTN_METRIC_CD) IN (COLLATE('BOOKINGS', 'en-ci-rtrim'), COLLATE('UNKNOWN', 'en-ci-rtrim'))
   AND COLLATE( RSTD.RSTD_DEL_RECORD_FLG, 'en-ci-rtrim') = 'N'
   --AND RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT >= 201401 
   /*BV_RSTD_BKGS_MSR_ANLZD_MY*/
   INNER JOIN /*BV_FISCAL_DAY_TO_YEAR*/
    {{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} RFDY
   ON RSTD.BOOKINGS_PROCESS_DATE = RFDY.CALENDAR_DATE
   AND  RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT >= (
     SELECT
      FISCAL_YEAR_MONTH_INT FROM
      {{ source('raw', 'WI_PRODUCT_HWSW_MONTH_CTRL') }}
    )
   WHERE
   COLLATE( RSTD.SERVICE_FLG, 'en-ci-rtrim') = 'N'
   AND COLLATE( NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') <> 'Service'
 UNION ALL
  --Annuity RSTD--
  SELECT
   CAST(0.00 AS DECIMAL(36, 8)) AS BOOKINGS_NET,
   CAST(0.00 AS DECIMAL(36, 8)) AS ANNUAL_NET,
   CAST(0.00 AS DECIMAL(36, 8)) AS MY_NET,
   CASE
    WHEN COLLATE(PRODUCT_CLASSIFICATION, 'en-ci-rtrim') = 'SOFTWARE'
     THEN BMA.DV_ANNUITY_AMT ELSE CAST(0.00 AS DECIMAL(18, 6))
   END AS ANNUITY_AMT,
   BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT AS PERIOD_ID,
   BMA.DV_SALES_ORDER_LINE_KEY,
   BMA.DV_ATTRIBUTION_CD,
   BMA.PRODUCT_KEY,
   BMA.SALES_TERRITORY_KEY,
   BMA.SALES_REP_NUMBER,
   RSTD.SALES_ORDER_KEY,
   BMA.DV_CONTRACT_DURATION AS CNTRCT_DURATION,
   BMA.RU_SERVICE_CONTRACT_START_DTM AS CONTRACT_START_DATE,
   BMA.RU_SERVICE_CONTRACT_END_DTM AS CONTRACT_END_DATE,
   BMA.DV_ANNUALIZED_FLG AS ANNUALIZD_FLAG,
   BMA.BKGS_MEASURE_TRANS_TYPE_CODE,
   BMA.CORPORATE_BOOKINGS_FLG,
   BMA.DV_REVENUE_RECOGNITION_FLG,
   BMA.SERVICE_FLG,
   RSTD.DV_PRODUCT_KEY,
   BMA.BILL_TO_CUSTOMER_KEY,
   BMA.SHIP_TO_CUSTOMER_KEY,
   RFDY.FISCAL_WEEK_NAME AS WEEK_NAME,
   RFDY.DV_FISCAL_YR_MNTH_WEEK_NUM_INT AS WEEK_ID,
   /*(SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),1,4) || (CASE WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='01' THEN 'Q1'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='02' THEN 'Q1'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='03' THEN 'Q1'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='04' THEN 'Q2'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='05' THEN 'Q2'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='06' THEN 'Q2'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='07' THEN 'Q3'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='08' THEN 'Q3'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='09' THEN 'Q3'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='10' THEN 'Q4'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='11' THEN 'Q4'
   WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='12' THEN 'Q4' ELSE -9999 END)) AS QUARTER_ID,*/
   BMA.BOOKINGS_MEASURE_KEY,
   BMA.BOOKINGS_PROCESS_DATE,
   RSTD.DV_NET_SPREAD_FLG NET_SPREAD_FLG,
   BMA.ADJUSTMENT_TYPE_CODE,
   BMA.ADJUSTMENT_CODE,
   RSTD.DV_SOURCE_ORDER_NUM_INT AS SOURCE_ORDER_NUMBER,
   RSTD.BK_POS_TRANSACTION_ID_INT AS POS_TRX_ID_INT,
   RSTD.DV_AR_TRX_LINE_KEY,
   RSTD.SOLD_TO_CUSTOMER_KEY,
   RSTD.DV_END_CUSTOMER_KEY  END_CUSTOMER_KEY,
   RSTD.END_CUSTOMER_KEY END_CUSTOMER_KEY_NOT_OFFSETED,
   RSTD.DV_FMV_FLG FMV_FLG,
   RSTD.SK_OFFER_ATTRIBUTION_ID_INT,
   NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD PRODUCT_CLASSIFICATION,
   --DUMMY COLUMN TO KEEP THE DEFAULT VIEW INTACT.
   CAST(1 AS NUMBER(38, 18)) AS ANNUITY_SWITCHING,
   NBCM.PARTNER_SITE_PARTY_KEY,
   RSTD.BK_OFFER_TYPE_NAME OFFER_TYPE_NAME,
   RSTD.ELA_FLG,
   RSTD.XCAT_FLG XCAT_FLAG,
   RSTD.RECURRING_OFFER_FLG RECURRING_OFFER_FLAG,
   --RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT AS QUARTER_NUMBER_INT,
   RSTD.DSV_FLG,
   RSTD.REVENUE_FLG,
   RSTD.IC_REVENUE_FLG,
   RSTD.REPLACEMENT_DEMO_FLG,
   RSTD.INTERNATIONAL_DEMO_FLG,
   RSTD.CHARGES_FLG,
   RSTD.MISC_FLG,
   NBCM.DV_ROUTE_TO_MARKET_CD ROUTE_TO_MARKET_CD,
   NBCM.DV_AS_OF_FSC_MTH_RTM_CD  AS_OF_FSC_MTH_RTM_CD,
   RSTD.TRANSACTION_DATETIME,
   RSTD.CANCEL_CODE,
   RSTD.DV_TRANSACTION_NAME  TRANSACTION_NAME,
   RSTD.CONVERSION_RT,
   RSTD.BK_SALES_ADJ_LINE_NUMBER_INT SALES_ADJ_LINE_NUMBER_INT,
   RSTD.BK_SALES_ADJ_NUMBER_INT  SALES_ADJ_NUMBER_INT,
   RSTD.REVENUE_TRANSFER_KEY,
   RSTD.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY,
   RSTD.DV_DEAL_ID  DEAL_ID,
   BMA.DV_FISCAL_YEAR_MONTH_INT AS FISCAL_YEAR_MTH_INT,
   RSTD.SALES_MOTION_CD,
   RSTD.SUMMARY_QUOTE_FLG,
   RSTD.ADJUSTMENT_DESCR_KEY,
   RSTD.DV_RECURRING_OFFER_CD,
   RSTD.SK_SALES_MOTION_ATTRIB_KEY,
   RSTD.WIPS_ORIGINATOR_ID_INT,
   /*Added as part of SFP Q4FY21 Rel*/
   NBCM.MAGIC_KEY_ID
   FROM
   {{ source('raw', 'MT_RSTD_BKGS_MSR_ANNUITY') }} BMA
   INNER JOIN
    {{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} RFDY
   ON          BMA.DV_ANNUITY_DATE = RFDY.CALENDAR_DATE
   AND  BMA.DV_FISCAL_YEAR_MONTH_INT >= (
     SELECT
      FISCAL_YEAR_MONTH_INT FROM
      {{ source('raw', 'WI_PRODUCT_HWSW_MONTH_CTRL') }}
    ) ,
   {{ source('raw', 'MT_RSTD_BKGS_MEASURE') }} RSTD
   INNER JOIN
    {{ source('raw', 'N_BOOKINGS_CHANNEL_MEASURE') }} NBCM
   ON RSTD.BOOKINGS_MEASURE_KEY = NBCM.BOOKINGS_MEASURE_KEY
   AND  RSTD.BOOKINGS_PROCESS_DATE = NBCM.BOOKINGS_PROCESS_DATE
   AND RSTD.BKGS_MEASURE_TRANS_TYPE_CODE = NBCM.BKGS_MEASURE_TRANS_TYPE_CODE
   INNER JOIN
    {{ source('raw', 'N_PRDT_TO_PRDT_CLSFTN_ALCTN') }} NPCA
   ON  NPCA.DV_FISCAL_YEAR_QUARTER_NUM_INT = RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT
   AND NPCA.PRODUCT_KEY = RSTD.PRODUCT_KEY
   AND RTRIM( NPCA.BK_PRDT_ALLCTN_METRIC_CD) IN (COLLATE('BOOKINGS', 'en-ci-rtrim'), COLLATE('UNKNOWN', 'en-ci-rtrim'))
   AND COLLATE( RSTD.RSTD_DEL_RECORD_FLG, 'en-ci-rtrim') = 'N'
   /*AND RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT >= 201401 */
   WHERE  1 = 1
   AND (BMA.BOOKINGS_MEASURE_KEY = RSTD.BOOKINGS_MEASURE_KEY
   AND BMA.BOOKINGS_PROCESS_DATE = RSTD.BOOKINGS_PROCESS_DATE
   AND BMA.BKGS_MEASURE_TRANS_TYPE_CODE = RSTD.BKGS_MEASURE_TRANS_TYPE_CODE
   AND BMA.SALES_REP_NUMBER = RSTD.SALES_REP_NUMBER
   AND BMA.SALES_TERRITORY_KEY = RSTD.SALES_TERRITORY_KEY)
   AND BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT <> -9999
   AND COLLATE( BMA.DV_SRVC_BOOKINGS_TYPE, 'en-ci-rtrim') = 'ANNUITY'
   AND COLLATE( BMA.SERVICE_FLG, 'en-ci-rtrim') = 'N'
   AND COLLATE( NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') <> 'SERVICE'
   AND COLLATE( NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') <> 'HARDWARE')T